// App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import './App.css';
import axios from 'axios';

// Home Page Component
const HomePage = () => (
  <div className="home-page">
    <h1>BAKERY SHOP</h1>
    <Link to="/store" className="btn btn-primary">
      Enter Store
    </Link>
  </div>
);

// Product List Component
const ProductList = ({ products, onQuantityChange }) => {
  return (
    <div className="product-list">
      {products.map((product) => (
        <div key={product.name} className={`product-card ${product.stock === 0 ? 'out-of-stock' : ''}`}>
          <h3>{product.name}</h3>
          <p>Price: ${product.price.toFixed(2)}</p>
          <div className="quantity-control">
            <button 
              onClick={() => onQuantityChange(product.name, -1)} 
              disabled={product.quantity <= 0}
            >
              -
            </button>
            <span>{product.quantity}</span>
            <button 
              onClick={() => onQuantityChange(product.name, 1)} 
              disabled={product.quantity >= product.stock}
            >
              +
            </button>
          </div>
          <p>In stock: {product.stock}</p>
        </div>
      ))}
    </div>
  );
};

// Order Summary Component
const OrderSummary = ({ cart, total, onCheckout }) => {
  return (
    <div className="order-summary">
      <h2>My Order</h2>
      <table>
        <thead>
          <tr>
            <th>Item</th>
            <th>Qty</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {cart.filter(item => item.quantity > 0).map((item) => (
            <tr key={item.name}>
              <td>{item.name}</td>
              <td>{item.quantity}</td>
              <td>${(item.price * item.quantity).toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className="total">
        <strong>Total: ${total.toFixed(2)}</strong>
      </div>
      <button 
        onClick={onCheckout} 
        disabled={total === 0}
        className="checkout-btn"
      >
        Place Order
      </button>
    </div>
  );
};

// Store Page Component
const StorePage = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchProducts = async () => {
      try {
        const response = await axios.get('/api/storage');
        const productsWithQuantity = response.data.storage.map(product => ({
          ...product,
          quantity: 0
        }));
        setProducts(productsWithQuantity);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();
  }, []);

  const handleQuantityChange = (productName, change) => {
    setProducts(prevProducts =>
      prevProducts.map(product =>
        product.name === productName
          ? {
              ...product,
              quantity: Math.max(
                0,
                Math.min(product.quantity + change, product.stock)
              )
            }
          : product
      )
    );
  };

  const handleCheckout = async () => {
    try {
      const orderItems = products
        .filter(product => product.quantity > 0)
        .map(({ name, quantity }) => ({ name, quantity }));

      await axios.post('/api/order', { items: orderItems });
      window.location.href = '/success';
    } catch (err) {
      alert(`Order failed: ${err.response?.data?.error || err.message}`);
    }
  };

  const total = products.reduce(
    (sum, product) => sum + product.price * product.quantity,
    0
  );

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div className="store-page">
      <h1>BAKERY SHOP</h1>
      <div className="store-container">
        <ProductList products={products} onQuantityChange={handleQuantityChange} />
        <OrderSummary 
          cart={products} 
          total={total} 
          onCheckout={handleCheckout} 
        />
      </div>
    </div>
  );
};

// Success Page Component
const SuccessPage = () => (
  <div className="success-page">
    <h1>Order received</h1>
    <h2>Thank you!</h2>
    <p>We have successfully received your order.</p>
    <Link to="/store" className="btn btn-primary">
      Submit another order
    </Link>
  </div>
);

// Main App Component
const App = () => (
  <Router>
    <Routes>
      <Route path="/" element={<HomePage />} />
      <Route path="/store" element={<StorePage />} />
      <Route path="/success" element={<SuccessPage />} />
    </Routes>
  </Router>
);

export default App;
